/* Lightweight Offline QR Code Generator (ISO/IEC 18004 Byte Mode, Error Correction L/M) */
(function(global) {
  "use strict";

  const EXP_TABLE = new Array(256);
  const LOG_TABLE = new Array(256);
  for (let i = 0; i < 8; i++) EXP_TABLE[i] = 1 << i;
  for (let i = 8; i < 256; i++) {
    EXP_TABLE[i] = EXP_TABLE[i - 4] ^ EXP_TABLE[i - 5] ^ EXP_TABLE[i - 6] ^ EXP_TABLE[i - 8];
  }
  for (let i = 0; i < 255; i++) LOG_TABLE[EXP_TABLE[i]] = i;

  function glog(n) {
    if (n < 1) throw new Error("glog(" + n + ")");
    return LOG_TABLE[n];
  }
  function gexp(n) {
    while (n < 0) n += 255;
    while (n >= 256) n -= 255;
    return EXP_TABLE[n];
  }

  function Polynomial(num, shift) {
    let offset = 0;
    while (offset < num.length && num[offset] === 0) offset++;
    this.num = new Array(num.length - offset + shift);
    for (let i = 0; i < num.length - offset; i++) this.num[i] = num[i + offset];
    for (let i = num.length - offset; i < this.num.length; i++) this.num[i] = 0;
  }
  Polynomial.prototype.get = function(index) { return this.num[index]; };
  Polynomial.prototype.getLength = function() { return this.num.length; };
  Polynomial.prototype.multiply = function(e) {
    const num = new Array(this.getLength() + e.getLength() - 1).fill(0);
    for (let i = 0; i < this.getLength(); i++) {
      for (let j = 0; j < e.getLength(); j++) {
        num[i + j] ^= gexp(glog(this.get(i)) + glog(e.get(j)));
      }
    }
    return new Polynomial(num, 0);
  };
  Polynomial.prototype.mod = function(e) {
    if (this.getLength() - e.getLength() < 0) return this;
    const ratio = glog(this.get(0)) - glog(e.get(0));
    const num = this.num.slice();
    for (let i = 0; i < e.getLength(); i++) {
      num[i] ^= gexp(glog(e.get(i)) + ratio);
    }
    return new Polynomial(num, 0).mod(e);
  };

  function getErrorCorrectPolynomial(errorCorrectLength) {
    let a = new Polynomial([1], 0);
    for (let i = 0; i < errorCorrectLength; i++) {
      a = a.multiply(new Polynomial([1, gexp(i)], 0));
    }
    return a;
  }

  // RS Block table for EC Level L (1): [totalCount, dataCount] per version 1..10
  const RS_BLOCKS_L = [
    null,
    [[26, 19]],
    [[44, 34]],
    [[70, 55]],
    [[100, 80]],
    [[134, 108]],
    [[172, 136]],
    [[196, 156]],
    [[242, 194]],
    [[292, 232]],
    [[346, 274]]
  ];

  const PATTERN_POS = [
    [],
    [],
    [6, 18],
    [6, 22],
    [6, 26],
    [6, 30],
    [6, 34],
    [6, 22, 38],
    [6, 24, 42],
    [6, 26, 46],
    [6, 28, 50]
  ];

  function getBCHTypeInfo(data) {
    let d = data << 10;
    while (getBCHDigit(d) - getBCHDigit(0x537) >= 0) {
      d ^= (0x537 << (getBCHDigit(d) - getBCHDigit(0x537)));
    }
    return ((data << 10) | d) ^ 0x5412;
  }
  function getBCHTypeNumber(data) {
    let d = data << 12;
    while (getBCHDigit(d) - getBCHDigit(0x1f25) >= 0) {
      d ^= (0x1f25 << (getBCHDigit(d) - getBCHDigit(0x1f25)));
    }
    return (data << 12) | d;
  }
  function getBCHDigit(data) {
    let digit = 0;
    while (data !== 0) { digit++; data >>>= 1; }
    return digit;
  }

  function BitBuffer() {
    this.buffer = [];
    this.length = 0;
  }
  BitBuffer.prototype.put = function(num, length) {
    for (let i = 0; i < length; i++) {
      this.putBit(((num >>> (length - i - 1)) & 1) === 1);
    }
  };
  BitBuffer.prototype.putBit = function(bit) {
    const bufIndex = Math.floor(this.length / 8);
    if (this.buffer.length <= bufIndex) this.buffer.push(0);
    if (bit) this.buffer[bufIndex] |= (0x80 >>> (this.length % 8));
    this.length++;
  };

  function encodeUtf8Bytes(str) {
    if (typeof TextEncoder !== "undefined") {
      return Array.from(new TextEncoder().encode(str));
    }
    const utf8 = unescape(encodeURIComponent(str));
    const arr = [];
    for (let i = 0; i < utf8.length; i++) arr.push(utf8.charCodeAt(i));
    return arr;
  }

  function selectVersion(byteLen) {
    for (let v = 1; v <= 10; v++) {
      const cap = RS_BLOCKS_L[v][0][1];
      const headerBits = 4 + (v < 10 ? 8 : 16);
      if (byteLen * 8 + headerBits <= cap * 8) return v;
    }
    return 10;
  }

  function createQrMatrix(text) {
    const bytes = encodeUtf8Bytes(text);
    const typeNumber = selectVersion(bytes.length);
    const rsBlock = RS_BLOCKS_L[typeNumber][0];
    const totalCount = rsBlock[0];
    const dataCount = rsBlock[1];

    const buffer = new BitBuffer();
    buffer.put(4, 4); // 8-bit byte mode
    buffer.put(bytes.length, typeNumber < 10 ? 8 : 16);
    for (let i = 0; i < bytes.length; i++) buffer.put(bytes[i], 8);

    if (buffer.length + 4 <= dataCount * 8) buffer.put(0, 4);
    while (buffer.length % 8 !== 0) buffer.putBit(false);
    while (buffer.buffer.length < dataCount) {
      buffer.put(0xec, 8);
      if (buffer.buffer.length >= dataCount) break;
      buffer.put(0x11, 8);
    }

    const dcdata = buffer.buffer.slice(0, dataCount);
    const ecCount = totalCount - dataCount;
    const rsPoly = getErrorCorrectPolynomial(ecCount);
    const rawPoly = new Polynomial(dcdata, rsPoly.getLength() - 1);
    const modPoly = rawPoly.mod(rsPoly);
    const ecdata = new Array(ecCount).fill(0);
    for (let i = 0; i < ecCount; i++) {
      const modIndex = i + modPoly.getLength() - ecCount;
      ecdata[i] = modIndex >= 0 ? modPoly.get(modIndex) : 0;
    }
    const codewords = dcdata.concat(ecdata);

    const moduleCount = typeNumber * 4 + 17;
    const modules = Array.from({ length: moduleCount }, () => new Array(moduleCount).fill(null));

    function setupPositionProbePattern(row, col) {
      for (let r = -1; r <= 7; r++) {
        if (row + r <= -1 || moduleCount <= row + r) continue;
        for (let c = -1; c <= 7; c++) {
          if (col + c <= -1 || moduleCount <= col + c) continue;
          if ((0 <= r && r <= 6 && (c === 0 || c === 6)) ||
              (0 <= c && c <= 6 && (r === 0 || r === 6)) ||
              (2 <= r && r <= 4 && 2 <= c && c <= 4)) {
            modules[row + r][col + c] = true;
          } else {
            modules[row + r][col + c] = false;
          }
        }
      }
    }

    setupPositionProbePattern(0, 0);
    setupPositionProbePattern(moduleCount - 7, 0);
    setupPositionProbePattern(0, moduleCount - 7);

    // Alignment patterns
    const pos = PATTERN_POS[typeNumber];
    for (let i = 0; i < pos.length; i++) {
      for (let j = 0; j < pos.length; j++) {
        const row = pos[i], col = pos[j];
        if (modules[row][col] !== null) continue;
        for (let r = -2; r <= 2; r++) {
          for (let c = -2; c <= 2; c++) {
            modules[row + r][col + c] = (Math.abs(r) === 2 || Math.abs(c) === 2 || (r === 0 && c === 0));
          }
        }
      }
    }

    // Timing patterns
    for (let i = 8; i < moduleCount - 8; i++) {
      if (modules[i][6] === null) modules[i][6] = (i % 2 === 0);
      if (modules[6][i] === null) modules[6][i] = (i % 2 === 0);
    }

    // Format info (EC Level L = 01, Mask 0 = 000 => 01000 = 8)
    const maskPattern = 0;
    const formatBits = getBCHTypeInfo((1 << 3) | maskPattern);
    for (let i = 0; i < 15; i++) {
      const mod = ((formatBits >> i) & 1) === 1;
      if (i < 6) modules[i][8] = mod;
      else if (i < 8) modules[i + 1][8] = mod;
      else modules[moduleCount - 15 + i][8] = mod;

      if (i < 8) modules[8][moduleCount - i - 1] = mod;
      else if (i < 9) modules[8][15 - i - 1 + 1] = mod;
      else modules[8][15 - i - 1] = mod;
    }
    modules[moduleCount - 8][8] = true;

    if (typeNumber >= 7) {
      const typeBits = getBCHTypeNumber(typeNumber);
      for (let i = 0; i < 18; i++) {
        const mod = ((typeBits >> i) & 1) === 1;
        modules[Math.floor(i / 3)][i % 3 + moduleCount - 8 - 3] = mod;
        modules[i % 3 + moduleCount - 8 - 3][Math.floor(i / 3)] = mod;
      }
    }

    // Map data with mask 0 ((row + col) % 2 === 0)
    let inc = -1;
    let row = moduleCount - 1;
    let bitIndex = 7;
    let byteIndex = 0;
    for (let col = moduleCount - 1; col > 0; col -= 2) {
      if (col === 6) col--;
      while (true) {
        for (let c = 0; c < 2; c++) {
          if (modules[row][col - c] === null) {
            let dark = false;
            if (byteIndex < codewords.length) {
              dark = (((codewords[byteIndex] >>> bitIndex) & 1) === 1);
            }
            if ((row + col - c) % 2 === 0) dark = !dark;
            modules[row][col - c] = dark;
            bitIndex--;
            if (bitIndex === -1) {
              byteIndex++;
              bitIndex = 7;
            }
          }
        }
        row += inc;
        if (row < 0 || moduleCount <= row) {
          row -= inc;
          inc = -inc;
          break;
        }
      }
    }
    return modules;
  }

  function renderQrToElement(container, text, size) {
    if (!container) return;
    const px = size || 132;
    const matrix = createQrMatrix(text);
    const count = matrix.length;
    const margin = 2;
    const total = count + margin * 2;
    let rects = "";
    for (let r = 0; r < count; r++) {
      for (let c = 0; c < count; c++) {
        if (matrix[r][c]) {
          rects += `<rect x="${c + margin}" y="${r + margin}" width="1" height="1" fill="#0f172a"/>`;
        }
      }
    }
    container.innerHTML = `<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 ${total} ${total}" width="${px}" height="${px}" shape-rendering="crispEdges" style="background:#ffffff;border-radius:8px;display:block;">${rects}</svg>`;
  }

  global.RobotQR = {
    render: renderQrToElement
  };
})(window);
